program='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr in (-1, 1):
                for dc in (-1, 1):
                    r2, c2 = r + dr, c + dc
                    if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
                        for rr, cc, sr, sc in (
                            (r - dr, c - dc, -dr, -dc),
                            (r2 + dr, c2 + dc, dr, dc),
                        ):
                            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                                out[rr][cc] = color
                                rr += sr
                                cc += sc
    return out
'''
